"""API routes for inspecting security alerts."""

from typing import List, Optional
from fastapi import APIRouter, Depends, HTTPException, Query, status

from app.core.config import settings
from app.models.alert import Alert
from app.repositories.alert_repository import (
    BaseAlertRepository,
    get_alert_repository,
)

router = APIRouter(prefix="/alerts", tags=["Security Alerts"])


@router.get(
    "",
    response_model=List[Alert],
    summary="List security alerts",
    description=(
        "Retrieve recent security abuse and anomaly alerts generated by the rule engine. "
        "Ordered newest first, with optional client_id and status filters."
    ),
)
def get_alerts(
    limit: int = Query(
        default=settings.DEFAULT_ALERTS_LIMIT,
        ge=1,
        le=settings.MAX_ALERTS_LIMIT,
        description=f"Maximum number of alerts to return (1 to {settings.MAX_ALERTS_LIMIT})",
    ),
    skip: int = Query(
        default=0,
        ge=0,
        description="Number of alerts to skip for pagination",
    ),
    client_id: Optional[str] = Query(
        default=None,
        description="Filter alerts by specific client ID",
    ),
    status_filter: Optional[str] = Query(
        default=None,
        alias="status",
        description="Filter alerts by status (e.g., 'open', 'acknowledged', 'resolved')",
    ),
    repository: BaseAlertRepository = Depends(get_alert_repository),
) -> List[Alert]:
    """Retrieve security alerts matching optional filter criteria."""
    return repository.get_alerts(
        limit=limit,
        skip=skip,
        client_id=client_id,
        status=status_filter,
    )


@router.get(
    "/{alert_id}",
    response_model=Alert,
    summary="Get single alert by ID",
    description="Retrieve full details for a specific security alert.",
    responses={
        200: {"description": "Alert details"},
        404: {"description": "Alert not found"},
    },
)
def get_alert(
    alert_id: str,
    repository: BaseAlertRepository = Depends(get_alert_repository),
) -> Alert:
    """Retrieve an alert by its unique UUID."""
    alert = repository.get_alert_by_id(alert_id)
    if alert is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Alert with ID '{alert_id}' not found",
        )
    return alert
